111	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_MUON_MIN_BLOCKS)
112	muon_update_kernel(
113	    ParamT* param, const float* orth,
114	    float neg_lr_scale, float decay_factor, int64_t N
115	) {
116	    const int64_t stride = prim::grid_stride() * UNROLL;
117	    const int64_t base0 = prim::grid_stride_index() * UNROLL;
118	    for (int64_t base = base0; base < N; base += stride) {
119	        #pragma unroll
120	        for (int u = 0; u < UNROLL; ++u) {
121	            const int64_t i = base + u;
122	            if (i < N) {
123	                muon_update_step(param, orth, neg_lr_scale, decay_factor, i);
124	            }
125	        }
126	    }
